  "severity": "critical",
  "host_observations": [
    {"host": "WS-DEV-22.corp.local", "role": "endpoint", "user": "r.morrison", "first_seen": "2032-09-09T11:18:08+0000", "last_seen": "2032-09-09T11:22:30+0000"}
