  "attack_progression": [
    {"step": 1, "tactic": "Outlook rule manifest staged in %TEMP%", "technique": "T1564.008", "what_happened": "At 2032-09-09 11:18:08 UTC, Sysmon EID 11 reports powershell.exe writing C:\\Users\\r.morrison\\AppData\\Local\\Temp\\p99_t03_rule_111808\\rule.xml (~700 bytes XML). The XML defines an Outlook rule with subject filters on security-sensitive keywords (password reset, verification code, security alert, invoice, payment).", "chain_reason": "Staging an inbox-rule manifest in TEMP is unusual for legitimate Outlook use (rules normally created via Outlook UI / New-InboxRule cmdlet)."},
    {"step": 2, "tactic": "O365 audit: New-InboxRule with external ForwardTo + MoveToFolder + MarkAsRead", "technique": "T1564.008", "what_happened": "At 11:18:42, O365 unified audit log records New-InboxRule by r.morrison@corp.local with Name='System Notification Filter', ForwardTo='attacker@external.example' (non-corp domain), MoveToFolder='RSS Feeds', MarkAsRead=true, StopProcessingRules=true. Rule 92220 triggered.", "chain_reason": "The triad ForwardTo external + MoveToFolder RSS Feeds + MarkAsRead is the canonical BEC inbox-rule hiding pattern."},
    {"step": 3, "tactic": "Registry EnableUnsafeClientMailRules check", "technique": "T1564.008", "what_happened": "At 11:19:12, Sysmon EID 13 reports read of HKCU\\Software\\Microsoft\\Office\\16.0\\Outlook\\Security\\EnableUnsafeClientMailRules. Rule 92221 triggered as legacy attack indicator.", "chain_reason": "Querying this key is a known attacker pre-step to enable RunScript inbox-rule actions."},
    {"step": 4, "tactic": "Wazuh FIM: new .rwz file in Outlook profile", "technique": "T1564.008", "what_happened": "At 11:19:38, Wazuh FIM (rule 550) reports a new .rwz file in C:\\Users\\r.morrison\\AppData\\Roaming\\Microsoft\\Outlook\\ — the persisted Outlook rules store has changed, consistent with a new rule being saved.", "chain_reason": "FIM corroborates the O365 audit-log evidence — the new rule was actually persisted client-side."}
  ],
  "time_window": {"start": "2032-09-09T11:18:08+0000", "end": "2032-09-09T11:22:30+0000"},
  "alert_count": 3,
  "unique_steps": 4
}
